EXEC sys.sp_executesql N''/* Only finalized, published grades and completed course enrollments count.
   The report does not define repeated-course handling; this view shows all completed attempts.
   One active band must match a score; overlapping bands should be avoided when editing GradeScale. */
CREATE VIEW dbo.vStudentCourseResults AS
SELECT s.StudentID,s.StudentCode,c.CourseCode,c.CourseName,c.Credits,
 cl.ClassCode, sem.SemesterCode,g.FinalScore,gs.GradeLetter,gs.GradePoint
FROM dbo.Students s
JOIN dbo.Enrollments e ON e.StudentID=s.StudentID AND e.EnrollmentStatus=''''COMPLETED''''
JOIN dbo.Classes cl ON cl.ClassID=e.ClassID
JOIN dbo.Courses c ON c.CourseID=cl.CourseID
JOIN dbo.Semesters sem ON sem.SemesterID=cl.SemesterID
JOIN dbo.Grades g ON g.EnrollmentID=e.EnrollmentID AND g.IsPublished=1
OUTER APPLY (SELECT TOP (1) sc.GradeLetter,sc.GradePoint
 FROM dbo.GradeScale sc WHERE sc.IsActive=1 AND g.FinalScore BETWEEN sc.MinScore AND sc.MaxScore
 ORDER BY sc.MinScore DESC) gs;'';
EXEC sys.sp_executesql N''CREATE VIEW dbo.vStudentGPA AS
SELECT StudentID,StudentCode,
 CAST(SUM(CASE WHEN GradePoint IS NOT NULL THEN Credits*GradePoint END) /
 NULLIF(SUM(CASE WHEN GradePoint IS NOT NULL THEN CONVERT(decimal(18,4),Credits) END),0) AS decimal(5,2)) AS CumulativeGPA,
 SUM(CASE WHEN GradePoint IS NOT NULL THEN Credits ELSE 0 END) AS CountedCredits
FROM dbo.vStudentCourseResults GROUP BY StudentID,StudentCode;'';
EXEC sys.sp_executesql N''CREATE VIEW dbo.vStudentSemesterGPA AS
SELECT StudentID,StudentCode,SemesterCode,
 CAST(SUM(CASE WHEN GradePoint IS NOT NULL THEN Credits*GradePoint END) /
 NULLIF(SUM(CASE WHEN GradePoint IS NOT NULL THEN CONVERT(decimal(18,4),Credits) END),0) AS decimal(5,2)) AS SemesterGPA,
 SUM(CASE WHEN GradePoint IS NOT NULL THEN Credits ELSE 0 END) AS CountedCredits
FROM dbo.vStudentCourseResults GROUP BY StudentID,StudentCode,SemesterCode;'';
EXEC sys.sp_executesql N''CREATE OR ALTER TRIGGER dbo.trg_Enrollments_RegistrationMatch ON dbo.Enrollments
AFTER INSERT, UPDATE AS
BEGIN
 SET NOCOUNT ON;
 IF EXISTS(SELECT 1 FROM inserted e JOIN dbo.CourseEnrollments r ON r.CourseEnrollmentID=e.CourseEnrollmentID
 JOIN dbo.Classes c ON c.ClassID=e.ClassID
 WHERE e.StudentID<>r.StudentID OR c.CourseID<>r.CourseID OR c.SemesterID<>r.SemesterID
 OR (e.EnrollmentStatus<>''''DROPPED'''' AND r.RegistrationStatus=''''DROPPED''''))
 THROW 51110, ''''Assignment must match registration student, course and semester; registration must not be dropped.'''',1;
END;'';
EXEC sys.sp_executesql N''CREATE OR ALTER TRIGGER dbo.trg_CourseEnrollments_ProtectAssignments ON dbo.CourseEnrollments
AFTER UPDATE AS
BEGIN
 SET NOCOUNT ON;
 IF EXISTS(SELECT 1 FROM inserted r JOIN dbo.Enrollments e ON e.CourseEnrollmentID=r.CourseEnrollmentID
 JOIN dbo.Classes c ON c.ClassID=e.ClassID
 WHERE e.StudentID<>r.StudentID OR c.CourseID<>r.CourseID OR c.SemesterID<>r.SemesterID
 OR (r.RegistrationStatus=''''DROPPED'''' AND e.EnrollmentStatus<>''''DROPPED''''))
 THROW 51111, ''''Registration change conflicts with an existing class assignment.'''',1;
END;'';
EXEC sys.sp_executesql N''CREATE OR ALTER TRIGGER dbo.trg_Classes_ProtectRegistrations ON dbo.Classes
AFTER UPDATE AS
BEGIN
 SET NOCOUNT ON;
 IF EXISTS(SELECT 1 FROM inserted c JOIN dbo.Enrollments e ON e.ClassID=c.ClassID
 JOIN dbo.CourseEnrollments r ON r.CourseEnrollmentID=e.CourseEnrollmentID
 WHERE c.CourseID<>r.CourseID OR c.SemesterID<>r.SemesterID)
 THROW 51112, ''''Cannot change course or semester of an assigned class.'''',1;
END;'';
EXEC sys.sp_executesql N''CREATE OR ALTER PROCEDURE dbo.uspRegisterCourse
 @StudentID int, @CourseID int, @SemesterID int,
 @CourseEnrollmentID int = NULL OUTPUT
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @StudentStatus varchar(20), @State varchar(15);
  SELECT @StudentStatus=StudentStatus FROM dbo.Students WITH(UPDLOCK,HOLDLOCK) WHERE StudentID=@StudentID;
  IF @StudentStatus IS NULL OR @StudentStatus<>''''ACTIVE'''' THROW 51120,''''Student is missing or inactive.'''',1;
  IF NOT EXISTS(SELECT 1 FROM dbo.Courses WHERE CourseID=@CourseID AND IsActive=1)
   THROW 51121,''''Course is missing or inactive.'''',1;
  IF NOT EXISTS(SELECT 1 FROM dbo.Semesters WHERE SemesterID=@SemesterID)
   THROW 51122,''''Semester not found.'''',1;
  SET @CourseEnrollmentID=NULL;
  SELECT @CourseEnrollmentID=CourseEnrollmentID,@State=RegistrationStatus
  FROM dbo.CourseEnrollments WITH(UPDLOCK,HOLDLOCK)
  WHERE StudentID=@StudentID AND CourseID=@CourseID AND SemesterID=@SemesterID;
  IF @CourseEnrollmentID IS NOT NULL AND @State<>''''DROPPED''''
   THROW 51123,''''Course is already registered in this semester.'''',1;
  IF @CourseEnrollmentID IS NULL
  BEGIN
   INSERT dbo.CourseEnrollments(StudentID,CourseID,SemesterID) VALUES(@StudentID,@CourseID,@SemesterID);
   SET @CourseEnrollmentID=CONVERT(int,SCOPE_IDENTITY());
  END
  ELSE
  BEGIN
   IF EXISTS(SELECT 1 FROM dbo.Enrollments e JOIN dbo.Grades g ON g.EnrollmentID=e.EnrollmentID
             WHERE e.CourseEnrollmentID=@CourseEnrollmentID)
    THROW 51124,''''Dropped registration has grades. Academic review is required.'''',1;
   UPDATE dbo.CourseEnrollments SET RegistrationStatus=''''REGISTERED'''',RegistrationDate=SYSUTCDATETIME()
    WHERE CourseEnrollmentID=@CourseEnrollmentID;
  END;
  COMMIT;
 END TRY
 BEGIN CATCH
  IF @@TRANCOUNT>0 ROLLBACK;
  THROW;
 END CATCH;
END;'';
EXEC sys.sp_executesql N''CREATE OR ALTER PROCEDURE dbo.uspAssignStudentToClass
 @CourseEnrollmentID int, @ClassID int
AS
BEGIN
 SET NOCOUNT ON; SET XACT_ABORT ON;
 BEGIN TRY
  BEGIN TRANSACTION;
  DECLARE @StudentID int,@CourseID int,@SemesterID int,@State varchar(15),
          @ClassCourse int,@ClassSemester int,@Capacity int,@ClassState varchar(15),@StudentState varchar(20);
  SELECT @StudentID=StudentID,@CourseID=CourseID,@SemesterID=SemesterID,@State=RegistrationStatus
  FROM dbo.CourseEnrollments WITH(UPDLOCK,HOLDLOCK) WHERE CourseEnrollmentID=@CourseEnrollmentID;
  IF @StudentID IS NULL OR @State<>''''REGISTERED'''' THROW 51130,''''Registration is missing or not available for assignment.'''',1;
  SELECT @StudentState=StudentStatus FROM dbo.Students WITH(HOLDLOCK) WHERE StudentID=@StudentID;
  IF @StudentState<>''''ACTIVE'''' THROW 51131,''''Student is inactive.'''',1;
  SELECT @ClassCourse=CourseID,@ClassSemester=SemesterID,@Capacity=Capacity,@ClassState=ClassStatus
  FROM dbo.Classes WITH(UPDLOCK,HOLDLOCK) WHERE ClassID=@ClassID;
  IF @ClassCourse IS NULL OR @ClassState<>''''OPEN'''' THROW 51132,''''Class is missing or not open.'''',1;
  IF @ClassCourse<>@CourseID OR @ClassSemester<>@SemesterID THROW 51133,''''Class course/semester does not match registration.'''',1;
  IF NOT EXISTS(SELECT 1 FROM dbo.Courses WHERE CourseID=@CourseID AND IsActive=1)
    THROW 51134,''''Course is inactive.'''',1;
  IF EXISTS(SELECT 1 FROM dbo.Enrollments WHERE CourseEnrollmentID=@CourseEnrollmentID AND EnrollmentStatus<>''''DROPPED'''')
   THROW 51135,''''Registration already has an active class assignment.'''',1;
  IF @Capacity IS NOT NULL AND (SELECT COUNT_BIG(*) FROM dbo.Enrollments
   WHERE ClassID=@ClassID AND EnrollmentStatus IN (''''ENROLLED'''',''''COMPLETED''''))>=@Capacity
   THROW 51136,''''Class is full.'''',1;
  IF EXISTS(SELECT 1 FROM dbo.Enrollments e JOIN dbo.Grades g ON g.EnrollmentID=e.EnrollmentID
   WHERE e.StudentID=@StudentID AND e.ClassID=@ClassID)
   THROW 51137,''''Previous assignment has a grade. Academic review is required.'''',1;
  IF EXISTS(SELECT 1 FROM dbo.Enrollments WHERE StudentID=@StudentID AND ClassID=@ClassID)
   UPDATE dbo.Enrollments SET EnrollmentStatus=''''ENROLLED'''',EnrollmentDate=SYSUTCDATETIME()
    WHERE StudentID=@StudentID AND ClassID=@ClassID;
  ELSE
   INSERT dbo.Enrollments(StudentID,ClassID,CourseEnrollmentID) VALUES(@StudentID,@ClassID,@CourseEnrollmentID);
  COMMIT;
 END TRY
 BEGIN CATCH
  IF @@TRANCOUNT>0 ROLLBACK;
  THROW;
 END CATCH;
END;'';
EXEC sys.sp_executesql N''CREATE OR ALTER PROCEDURE dbo.uspEnrollStudent @StudentID int,@ClassID int
AS
BEGIN
 SET NOCOUNT ON;
 THROW 51140,''''Old combined enrollment is disabled. Use uspRegisterCourse, then uspAssignStudentToClass.'''',1;
END;'';
EXEC sys.sp_executesql N''CREATE OR ALTER VIEW dbo.vCourseEnrollmentStatus AS
SELECT r.CourseEnrollmentID,r.StudentID,s.StudentCode,s.FullName,
 r.CourseID,c.CourseCode,c.CourseName,r.SemesterID,t.SemesterCode,
 r.RegistrationDate,r.RegistrationStatus,e.EnrollmentID,e.ClassID,cl.ClassCode,e.EnrollmentStatus
FROM dbo.CourseEnrollments r
JOIN dbo.Students s ON s.StudentID=r.StudentID
JOIN dbo.Courses c ON c.CourseID=r.CourseID
JOIN dbo.Semesters t ON t.SemesterID=r.SemesterID
LEFT JOIN dbo.Enrollments e ON e.CourseEnrollmentID=r.CourseEnrollmentID AND e.EnrollmentStatus<>''''DROPPED''''
LEFT JOIN dbo.Classes cl ON cl.ClassID=e.ClassID;'';

 COMMIT;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK;
 THROW;
END CATCH;
